{public async ValueTask<IReadOnlyCollection<ReturnRequest>>ListAsync(ReturnFilter f,CancellationToken t){await using var c=await Open(t);await using var cmd=Command("",c);var w=new List<string>();if(f.Processed is not null){w.Add("[Procesada]=@Processed");cmd.Parameters.Add("@Processed",SqlDbType.Bit).Value=f.Processed;}if(!string.IsNullOrWhiteSpace(f.DriverCode)){w.Add("[CodChofer]=@Driver");cmd.Parameters.Add("@Driver",SqlDbType.NVarChar,50).Value=f.DriverCode.Trim();}if(f.Number is not null){w.Add("[DocNum]=@Number");cmd.Parameters.Add("@Number",SqlDbType.Int).Value=f.Number;}cmd.CommandText=$"SELECT TOP(500) [DocNum],MIN([FechaNota]) [FechaNota],MAX([CodChofer]) [CodChofer],MAX([NombreChofer]) [NombreChofer],MAX([CodCliente]) [CodCliente],MAX([NombreCliente]) [NombreCliente],MAX([Credito]) [Credito],SUM([Total]) [Total],MAX([NumFactura]) [NumFactura],MAX([Motivo]) [Motivo],MAX([Procesada]) [Procesada],MAX([DocEntry]) [DocEntry],MAX([Ruta]) [Ruta],MAX([NumMarchamo]) [NumMarchamo],MAX([Comentario]) [Comentario] FROM [dbo].[Devoluciones]{(w.Count==0?"":" WHERE "+string.Join(" AND ",w))} GROUP BY [DocNum] ORDER BY [DocNum] DESC";var list=new List<ReturnRequest>();await using var r=await cmd.ExecuteReaderAsync(t);while(await r.ReadAsync(t))list.Add(Header(r,[]));return list;}
 public async ValueTask<ReturnRequest?>GetAsync(int n,CancellationToken t){await using var c=await Open(t);ReturnRequest? h;await using(var cmd=Command("SELECT TOP(1) [DocNum],[FechaNota],[CodChofer],[NombreChofer],[CodCliente],[NombreCliente],[Credito],[Total],[NumFactura],[Motivo],[Procesada],[DocEntry],[Ruta],[NumMarchamo],[Comentario] FROM [dbo].[Devoluciones] WHERE [DocNum]=@Number",c)){cmd.Parameters.Add("@Number",SqlDbType.Int).Value=n;await using var r=await cmd.ExecuteReaderAsync(t);h=await r.ReadAsync(t)?Header(r,[]):null;}if(h is null)return null;var lines=new List<ReturnLine>();await using(var cmd=Command("SELECT D.[NumLinea],D.[ItemCode],D.[ItemName],D.[Precio],D.[Quantity],D.[Porc_Desc_Fijo],D.[Porc_Desc_Promo],D.[Porc_Imp],D.[Total],D.[Motivo],D.[Comentarios],ISNULL(M.[Bodega],'') [Bodega] FROM [dbo].[DevolucionesDetalle] D LEFT JOIN [dbo].[MotivoDevolucion] M ON M.[Codigo]=D.[Motivo] OR M.[Descripcion]=D.[Motivo] WHERE D.[DocNum]=@Number ORDER BY D.[NumLinea]",c)){cmd.Parameters.Add("@Number",SqlDbType.Int).Value=n;await using var r=await cmd.ExecuteReaderAsync(t);while(await r.ReadAsync(t))lines.Add(new(Convert.ToInt32(r["NumLinea"]),S(r,"ItemCode"),S(r,"ItemName"),D(r,"Precio"),D(r,"Quantity"),D(r,"Porc_Desc_Fijo"),D(r,"Porc_Desc_Promo"),D(r,"Porc_Imp"),D(r,"Total"),S(r,"Motivo"),S(r,"Comentarios"),S(r,"Bodega")));}return h with{Lines=lines};}
 public async ValueTask<bool>MarkProcessedAsync(int n,int entry,CancellationToken t){await using var c=await Open(t);await using var tx=(SqlTransaction)await c.BeginTransactionAsync(t);try{await using var a=Command("UPDATE [dbo].[Devoluciones] SET [Procesada]=1,[DocEntry]=@Entry WHERE [DocNum]=@Number AND ISNULL([Procesada],0)<>1",c,tx);a.Parameters.Add("@Entry",SqlDbType.Int).Value=entry;a.Parameters.Add("@Number",SqlDbType.Int).Value=n;var changed=await a.ExecuteNonQueryAsync(t);await using var b=Command("UPDATE [dbo].[DevolucionesDetalle] SET [Procesada]=1 WHERE [DocNum]=@Number",c,tx);b.Parameters.Add("@Number",SqlDbType.Int).Value=n;await b.ExecuteNonQueryAsync(t);await tx.CommitAsync(t);return changed>0;}catch{await tx.RollbackAsync(t);throw;}}
 private static ReturnRequest Header(SqlDataReader r,IReadOnlyCollection<ReturnLine> lines)=>new(Convert.ToInt32(r["DocNum"]),DateOnly.FromDateTime(Convert.ToDateTime(r["FechaNota"])),S(r,"CodChofer"),S(r,"NombreChofer"),S(r,"CodCliente"),S(r,"NombreCliente"),B(r,"Credito"),D(r,"Total"),S(r,"NumFactura"),S(r,"Motivo"),B(r,"Procesada"),r["DocEntry"] is DBNull?null:Convert.ToInt32(r["DocEntry"]),S(r,"Ruta"),S(r,"NumMarchamo"),S(r,"Comentario"),lines);private static string S(SqlDataReader r,string n)=>Convert.ToString(r[n])?.Trim()??"";private static decimal D(SqlDataReader r,string n)=>r[n] is DBNull?0:Convert.ToDecimal(r[n]);private static bool B(SqlDataReader r,string n){if(r[n] is DBNull)return false;if(r[n] is bool b)return b;var s=Convert.ToString(r[n])?.Trim();return s is "1" or "SI" or "Sí" or "TRUE" or "True" or "Y";}private async ValueTask<SqlConnection>Open(CancellationToken t){var c=new SqlConnection(connectionString);await c.OpenAsync(t);return c;}private SqlCommand Command(string s,SqlConnection c,SqlTransaction? t=null)=>new(s,c,t){CommandTimeout=timeout};}
